CREATE INDEX idx_users_region_signup ON users(region, signup_date);
CREATE INDEX idx_orders_user_id ON orders(user_id, id, amount);
CREATE INDEX idx_users_id_region ON users(id, region, name, signup_date);

SELECT u.id, u.name, u.region, COUNT(o.id) AS order_count, SUM(o.amount) AS total_spent
FROM users u
LEFT JOIN orders o ON u.id = o.user_id
WHERE u.region = 'EUROPE'
  AND u.signup_date <= date('now', '-4 years')
GROUP BY u.id, u.name, u.region
HAVING COUNT(o.id) > 2
ORDER BY total_spent DESC;
